// Calculate the 48-hour window for sending intake forms
const now = new Date();

// Calculate target time: 48 hours from now
const target48hr = new Date(now.getTime() + (48 * 60 * 60 * 1000));

// Create date range (47-49 hours to account for hourly runs)
const windowStart = new Date(now.getTime() + (47 * 60 * 60 * 1000));
const windowEnd = new Date(now.getTime() + (49 * 60 * 60 * 1000));

// Format dates for Google Sheets filtering
const formatDate = (date) => {
  const month = String(date.getMonth() + 1).padStart(2, '0');
  const day = String(date.getDate()).padStart(2, '0');
  const year = date.getFullYear();
  return `${month}/${day}/${year}`;
};

const targetDate = formatDate(target48hr);

return {
  json: {
    now: now.toISOString(),
    target48hr: target48hr.toISOString(),
    targetDate: targetDate,
    windowStart: windowStart.toISOString(),
    windowEnd: windowEnd.toISOString()
  }
};

// Filter appointments that need intake forms sent
const appointments = $input.all();
const targetDate = $('Calculate 48hr Window').first().json.targetDate;

const needsForm = [];

for (const item of appointments) {
  const apt = item.json;

  // Skip if no date or status
  if (!apt.Date || !apt.Status) continue;

  // Parse appointment date (format: MM/DD/YYYY)
  const aptDate = apt.Date;

  // Check conditions:
  // 1. Appointment date matches 48hr window
  // 2. Status is SCHEDULED
  // 3. Form not already sent (Form_Link_Sent is not "Yes")
  // 4. Patient has phone number
  // 5. Patient has insurance info (for intake form context)

  const dateMatch = aptDate === targetDate;
  const isScheduled = apt.Status === 'SCHEDULED';
  const formNotSent = apt.Form_Link_Sent !== 'Yes';
  const hasPhone = apt.Phone && apt.Phone.trim() !== '';

  if (dateMatch && isScheduled && formNotSent && hasPhone) {
    // Generate unique appointment ID for tracking
    const appointmentId = `APT-${apt.Date.replace(/\//g, '')}-${apt.Time.replace(/:/g, '').replace(/ /g, '')}-${apt.Patient_Name.replace(/ /g, '-')}`;

    // Create Typeform URL with hidden fields
    const typeformBaseUrl = process.env.TYPEFORM_FORM_URL || 'https://form.typeform.com/to/YOUR_FORM_ID';

    // Add hidden fields to track patient context
    const hiddenFields = [
      `patient_name=${encodeURIComponent(apt.Patient_Name)}`,
      `appointment_id=${encodeURIComponent(appointmentId)}`,
      `phone=${encodeURIComponent(apt.Phone)}`,
      `appointment_date=${encodeURIComponent(apt.Date)}`,
      `appointment_time=${encodeURIComponent(apt.Time)}`,
      `insurance_company=${encodeURIComponent(apt.Insurance_Company || '')}`,
      `member_id=${encodeURIComponent(apt.Member_ID || '')}`
    ];

    const formUrl = `${typeformBaseUrl}?${hiddenFields.join('&')}`;

    needsForm.push({
      json: {
        ...apt,
        appointmentId: appointmentId,
        formUrl: formUrl,
        rowNumber: item.json.rowNumber || appointments.indexOf(item) + 2 // +2 for header row and 0-index
      }
    });
  }
}

if (needsForm.length === 0) {
  // No appointments need forms, return empty to stop workflow
  return [];
}

return needsForm;
